#!/usr/bin/env bash
# Generated by `factory install`; the factory owns this file and `factory update` overwrites it.
#
# SessionStart hook. Reads the factory version the stubs call, fetches that commit into
# .factory/ and copies its skills into .claude/skills/. It runs nothing it downloaded: the
# copy is done here, so session start executes only this committed file. It never blocks a
# session: on any failure it prints one warning and exits 0.
#
# Trust: the stubs' ref decides which skills sessions follow, as it decides what CI runs.
# A release line (@v0.2) changes only through the factory's release workflow; @main changes
# with every factory merge, which is right only for the test repository.

set -u

warn() { echo "factory: skills not updated: $*" >&2; }

materialize() {
  local root stub f uses repo ref sha tmp tarball name current=true
  root="${CLAUDE_PROJECT_DIR:-$(git rev-parse --show-toplevel 2>/dev/null)}" || return 1
  cd "$root" || return 1

  stub=""
  for f in .github/workflows/factory-*.yml; do
    [ -f "$f" ] && { stub="$f"; break; }
  done
  [ -n "$stub" ] || { echo "no .github/workflows/factory-*.yml"; return 1; }
  uses="$(grep -h -m1 -E 'uses:.*\.github/workflows/stage\.yml@' "$stub" | sed -E 's/.*uses:[[:space:]]*//; s/[[:space:]]*(#.*)?$//')"
  [ -n "$uses" ] || { echo "no stage.yml reference in $stub"; return 1; }
  repo="${uses%%/.github/*}"
  ref="${uses##*@}"

  # Resolve REF to a commit: anonymously first, then with the user's gh login (private factory).
  if [[ "$ref" =~ ^[0-9a-f]{40}$ ]]; then
    sha="$ref"
  else
    sha="$(GIT_TERMINAL_PROMPT=0 git ls-remote "https://github.com/$repo" "refs/tags/$ref^{}" "refs/tags/$ref" "refs/heads/$ref" 2>/dev/null | head -1 | cut -f1)"
    if [ -z "$sha" ] && command -v gh >/dev/null; then
      sha="$(gh api "repos/$repo/commits/$ref" --jq .sha 2>/dev/null)"
    fi
  fi
  [ -n "$sha" ] || { echo "can't resolve $ref of $repo"; return 1; }

  for d in .factory/skills/*/; do
    [ -d "$d" ] || continue
    name="$(basename "$d")"
    [ -e ".claude/skills/$name" ] || current=false
  done
  [ -d .factory/skills ] || current=false
  if [ "$current" = true ] && [ "$(cat .factory/.sha 2>/dev/null)" = "$sha" ]; then
    return 0
  fi

  tmp="$(mktemp -d)" || return 1
  tarball="$tmp/factory.tar.gz"
  if ! curl -fsSL --max-time 60 "https://codeload.github.com/$repo/tar.gz/$sha" -o "$tarball" 2>/dev/null; then
    if ! { command -v gh >/dev/null && gh api "repos/$repo/tarball/$sha" > "$tarball" 2>/dev/null; }; then
      rm -rf "$tmp"; echo "can't download $repo at ${sha:0:7}"; return 1
    fi
  fi
  mkdir "$tmp/x"
  if ! tar -xzf "$tarball" -C "$tmp/x" --strip-components=1; then
    rm -rf "$tmp"; echo "bad download"; return 1
  fi
  rm -rf .factory
  mkdir -p .factory
  if ! cp -R "$tmp/x/." .factory/; then rm -rf "$tmp"; return 1; fi
  rm -rf "$tmp"
  printf '%s\n' "$sha" > .factory/.commit
  copy_skills || return 1
  # .sha marks the copy done, so it's written only once the skills are in place: a failed
  # copy is retried next session.
  printf '%s\n' "$sha" > .factory/.sha
}

# copy_skills: .factory/skills/<name> into .claude/skills/<name>, except a skill this
# repository has committed itself (its own fork), which stays as it is.
copy_skills() {
  local d name
  mkdir -p .claude/skills || return 1
  for d in .factory/skills/*/; do
    name="$(basename "$d")"
    [ -f "$d/SKILL.md" ] || continue
    [ -z "$(git ls-files -- ".claude/skills/$name")" ] || continue
    rm -rf ".claude/skills/$name"
    cp -R "${d%/}" ".claude/skills/$name" || return 1
    find ".claude/skills/$name" \( -name __pycache__ -o -name '*.pyc' -o -name .DS_Store \) -exec rm -rf {} + 2>/dev/null
  done
  return 0
}

if ! msg="$(materialize 2>&1)"; then
  warn "$(printf '%s' "$msg" | tail -1)"
fi
exit 0
